-- =====================================================================
-- Memorepe — Crea el banco "Balotario MTC A-I – Examen de reglas de tránsito (Perú)"
-- 200 preguntas del balotario oficial del MTC (clase A, categoría I), 67 con imagen.
-- Correr COMPLETO una vez en el SQL Editor de Supabase. Si ya existe, no hace nada.
-- =====================================================================
do $$
declare
  v_user uuid;
  v_quiz uuid;
  v_q uuid;
begin
  select id into v_user from users where username = 'memorepe';
  if v_user is null then raise exception 'No existe el usuario @memorepe'; end if;
  if exists (select 1 from quizzes where title = 'Balotario MTC A-I – Examen de reglas de tránsito (Perú)') then raise notice 'Ya existe'; return; end if;
  values (v_user, 'Balotario MTC A-I – Examen de reglas de tránsito (Perú)', 'Las 200 preguntas del balotario oficial del MTC para el examen de reglas de tránsito de la licencia A-I en Perú, con señales y respuestas correctas.', 'otro', 'conducir', 'es', 'public', 'MTC Perú', 'Licencia de conducir A-I', 'balotario-mtc-a-i-examen-reglas-transito-peru')
  returning id into v_quiz;
  update quizzes set question_count = (select count(*) from questions where quiz_id = v_quiz) where id = v_quiz;
end $$;
